            if static_ip is not None:
                raise ResourceError(
                    f"static address {ipaddress.IPv4Address(static_ip)} for {user!r} "
                    "already in use"
                )
            raise ResourceError("address pool exhausted")

        # 全部校验通过后再落库，杜绝失败残留。
        self._commit_session(sid, user, pool_id, ip_int, now_ms)

