    canonical_head = {
        "版本": 1,
        "事件": [
            {
                "序号": seq,
                "类型": etype,
                "时刻": ev_now,
                "会话": sid,
                "用户": user,
                "地址池": pool_id,
                "地址": address,
                "累计字节": total,
                "原因": reason,
                "前哈希": stored_prev,
                "哈希": digest,
            }
            for (
                seq, etype, ev_now, sid, user, pool_id, address, total,
                reason, stored_prev, digest,
            ) in events
        ],
        "会话": [
            {"会话": sid, "累计字节": total, "最近时刻": last}
            for sid, total, last in rows
        ],
        "尾哈希": tail_hash,
    }
    blob = json.dumps(canonical_head, ensure_ascii=False, separators=(",", ":"))
    if hashlib.sha256(blob.encode("utf-8")).hexdigest() != summary:
        raise ValueError("计费.摘要 does not match the canonical object")
