    }
    recomputed_stats_summary = hashlib.sha256(
        recode(canon_stats_head).encode("utf-8")
    ).hexdigest()
    if recomputed_stats_summary != stats_summary:
        raise ValueError("统计 摘要 does not match canonical object")
