            (user, str(ipaddress.IPv4Address(pool.static[user])))
            for user in sorted(pool.static)
        )
        pool_specs.append((pool_id, pool.cidr, reserved, static))
    templates = tuple(
        (template_id,) + self._templates[template_id]

